package com.nextrade.client.service; import java.time.*; import java.util.*; public final class PortfolioQueryService {private final UUID componentId=UUID.randomUUID();private final Map<String,Object> state=new LinkedHashMap<>();public UUID componentId(){return componentId;}public String description(){return "Portfolio query facade";}public synchronized void put(String key,Object value){state.put(key,value);}public synchronized Optional<Object> get(String key){return Optional.ofNullable(state.get(key));}public synchronized Map<String,Object> snapshot(){return Map.copyOf(state);}public Instant now(){return Instant.now();}}
